import pytest

DEFAULTS: dict[str, str] = {"mode": "fast", "level": "3"}


def settings(keys: list[str], values: list[str]) -> list[str]:
    """Overlay the given settings on the defaults mode=fast and level=3.

    `keys[i]` is set to `values[i]`. Returns the resulting values in the
    order mode, level, then every other key in the order it first appears
    in `keys`. If a key repeats, the last value given wins and the key
    keeps the position of its first appearance. Raises ValueError if
    `keys` and `values` differ in length.
    """
    if len(keys) != len(values):
        raise ValueError("keys and values must have the same length")
    merged: dict[str, str] = dict(DEFAULTS)
    for k, v in zip(keys, values, strict=True):
        merged[k] = v
    return list(merged.values())


def test_defaults_when_empty() -> None:
    assert settings([], []) == ["fast", "3"]


def test_override_mode_only() -> None:
    assert settings(["mode"], ["slow"]) == ["slow", "3"]


def test_override_level_only() -> None:
    assert settings(["level"], ["9"]) == ["fast", "9"]


def test_override_both_in_reverse_order() -> None:
    assert settings(["level", "mode"], ["1", "safe"]) == ["safe", "1"]


def test_extra_keys_follow_in_given_order() -> None:
    assert settings(["z", "a", "m"], ["1", "2", "3"]) == ["fast", "3", "1", "2", "3"]


def test_extra_keys_mixed_with_known_keys() -> None:
    assert settings(
        ["color", "level", "name", "mode"],
        ["red", "7", "bob", "slow"],
    ) == ["slow", "7", "red", "bob"]


def test_duplicate_known_key_last_wins() -> None:
    assert settings(["mode", "mode"], ["a", "b"]) == ["b", "3"]


def test_duplicate_extra_key_last_wins_first_position() -> None:
    assert settings(["x", "y", "x"], ["1", "2", "3"]) == ["fast", "3", "3", "2"]


def test_empty_string_value_is_kept() -> None:
    assert settings(["mode", "x"], ["", ""]) == ["", "3", ""]


def test_does_not_mutate_defaults_or_inputs() -> None:
    keys = ["mode", "x"]
    values = ["slow", "1"]
    settings(keys, values)
    assert keys == ["mode", "x"]
    assert values == ["slow", "1"]
    assert DEFAULTS == {"mode": "fast", "level": "3"}
    assert settings([], []) == ["fast", "3"]


def test_length_mismatch_raises() -> None:
    with pytest.raises(ValueError):
        settings(["mode"], [])
    with pytest.raises(ValueError):
        settings([], ["x"])

